"""
services/corpus_service.py
==========================
Cinephile Universe Corpus Engine.
Manages a curated database of top-tier cinema masterworks spanning
Sight & Sound 250, Criterion Collection, Letterboxd Top 1000, Palme d'Or,
Venice/Berlin winners, and historical film movements with rich craft metadata.

Features:
- Instant in-memory / SQLite caching (< 2ms retrieval).
- Balanced 3-Era Temporal Structure:
  1. Contemporary Era (2010–2026)
  2. Modern Cult & Indie Renaissance (1980–2009)
  3. Golden Age Monoliths (< 1980)
- Rich Craft representation (Director, DoP, Composer, Screenwriter, Studio, Country, Era).
"""

import os
import sqlite3
import json
import logging
from typing import List, Dict, Any, Optional

logger = logging.getLogger(__name__)

DB_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "instance")
CORPUS_DB_PATH = os.path.join(DB_DIR, "cinephile_corpus.db")

_IN_MEMORY_CORPUS_CACHE: Optional[List[Dict[str, Any]]] = None


def _init_corpus_db():
    """Initializes the SQLite corpus schema."""
    os.makedirs(DB_DIR, exist_ok=True)
    with sqlite3.connect(CORPUS_DB_PATH) as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS curated_films (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                movie_key TEXT UNIQUE,
                title TEXT NOT NULL,
                year INTEGER NOT NULL,
                director TEXT NOT NULL,
                genre TEXT NOT NULL,
                cinematographer TEXT DEFAULT '',
                composer TEXT DEFAULT '',
                screenwriter TEXT DEFAULT '',
                studios TEXT DEFAULT '',
                lead_actors TEXT DEFAULT '',
                country TEXT DEFAULT 'US',
                language TEXT DEFAULT 'en',
                overview TEXT DEFAULT '',
                poster TEXT DEFAULT '',
                tv_show INTEGER DEFAULT 0,
                canon_tier TEXT DEFAULT 'landmark',
                movement_tags TEXT DEFAULT '',
                rating_score REAL DEFAULT 8.0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.execute("CREATE INDEX IF NOT EXISTS idx_curated_key ON curated_films(movie_key)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_curated_director ON curated_films(director)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_curated_genre ON curated_films(genre)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_curated_year ON curated_films(year)")


def _normalize_key(title: str, year: Any) -> str:
    import re
    t = re.sub(r"[^\w\s]", "", str(title or "").lower()).strip()
    t = re.sub(r"\s+", "", t)
    y = str(year or "").strip()[:4]
    return f"{t}_{y}"


