def seed_corpus_database(force_reseed: bool = False):
    """Seeds the SQLite database with the curated cinephile masterworks."""
    _init_corpus_db()
    with sqlite3.connect(CORPUS_DB_PATH) as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM curated_films")
        count = cursor.fetchone()[0]
        if count >= len(CORE_CINEPHILE_MASTERWORKS) and not force_reseed:
            return

        logger.info(f"[CORPUS SERVICE] Seeding {len(CORE_CINEPHILE_MASTERWORKS)} curated films into SQLite...")
        for film in CORE_CINEPHILE_MASTERWORKS:
            key = _normalize_key(film["title"], film["year"])
            cursor.execute("SELECT poster FROM curated_films WHERE movie_key = ?", (key,))
            existing_row = cursor.fetchone()
            existing_poster = existing_row[0] if existing_row else ""
            poster_to_use = film.get("poster") or existing_poster or ""

            cursor.execute("""
                INSERT OR REPLACE INTO curated_films 
                (movie_key, title, year, director, genre, cinematographer, composer, screenwriter, studios, lead_actors, country, language, overview, poster, tv_show, canon_tier, movement_tags, rating_score)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                key,
                film["title"],
                int(film["year"]),
                film["director"],
                film["genre"],
                film.get("cinematographer", ""),
                film.get("composer", ""),
                film.get("screenwriter", ""),
                film.get("studios", ""),
                film.get("lead_actors", ""),
                film.get("country", "US"),
                film.get("language", "en"),
                film.get("overview", ""),
                poster_to_use,
                film.get("tv_show", 0),
                film.get("canon_tier", "landmark"),
                film.get("movement_tags", ""),
                film.get("rating_score", 8.5)
            ))
        conn.commit()
        logger.info("[CORPUS SERVICE] Seeding complete!")


def get_all_curated_films() -> List[Dict[str, Any]]:
    """
    Retrieves all curated masterworks with high-speed in-memory caching (< 2ms).
    """
    global _IN_MEMORY_CORPUS_CACHE
    if _IN_MEMORY_CORPUS_CACHE is not None:
        return _IN_MEMORY_CORPUS_CACHE

    _init_corpus_db()
    seed_corpus_database(force_reseed=False)

    with sqlite3.connect(CORPUS_DB_PATH) as conn:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM curated_films ORDER BY rating_score DESC, year DESC")
        rows = cursor.fetchall()
        films = [dict(r) for r in rows]

    _IN_MEMORY_CORPUS_CACHE = films
    return _IN_MEMORY_CORPUS_CACHE
